insert into public.student_offers (id, name, provider, category, summary, eligibility, how_to_verify, url, countries, university_ids, status, source_url, last_verified, sort_order) values ('github_student_pack', 'GitHub Student Developer Pack', 'GitHub', 'developer', 'Free access to a bundle of developer tools and services from GitHub and its partners.', 'Enrolled in a degree or diploma program, at least 13 years old, with a personal GitHub account.', 'School email address, or proof of current enrollment such as a student ID or transcript.', 'https://education.github.com/pack', array[]::text[], array[]::text[], 'active', 'https://help.github.com/articles/applying-for-a-student-developer-pack', '2026-10-22', 0) on conflict (id) do update set name = excluded.name, provider = excluded.provider, category = excluded.category, summary = excluded.summary, eligibility = excluded.eligibility, how_to_verify = excluded.how_to_verify, url = excluded.url, countries = excluded.countries, university_ids = excluded.university_ids, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.student_offers (id, name, provider, category, summary, eligibility, how_to_verify, url, countries, university_ids, status, source_url, last_verified, sort_order) values ('jetbrains_student', 'JetBrains free student license', 'JetBrains', 'developer', 'Free individual licenses for JetBrains tools (such as IntelliJ IDEA and PyCharm), valid one year and renewable while you study.', 'Enrolled at an accredited school, college or university in a program of a year or more of full-time study.', 'School email address, an ISIC card, or a GitHub Student Developer Pack account.', 'https://www.jetbrains.com/student/', array[]::text[], array[]::text[], 'active', 'https://www.jetbrains.com/student/', '2026-10-22', 1) on conflict (id) do update set name = excluded.name, provider = excluded.provider, category = excluded.category, summary = excluded.summary, eligibility = excluded.eligibility, how_to_verify = excluded.how_to_verify, url = excluded.url, countries = excluded.countries, university_ids = excluded.university_ids, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.student_offers (id, name, provider, category, summary, eligibility, how_to_verify, url, countries, university_ids, status, source_url, last_verified, sort_order) values ('figma_education', 'Figma for Education', 'Figma', 'design', 'Figma''s Education plan, free for verified students (Professional plan for higher education).', 'Students and educators, 13 or older, applying with their school email.', 'Apply at figma.com/education; verification is done by SheerID.', 'https://www.figma.com/education/', array[]::text[], array[]::text[], 'active', 'https://help.figma.com/hc/en-us/articles/360041061214', '2026-10-22', 2) on conflict (id) do update set name = excluded.name, provider = excluded.provider, category = excluded.category, summary = excluded.summary, eligibility = excluded.eligibility, how_to_verify = excluded.how_to_verify, url = excluded.url, countries = excluded.countries, university_ids = excluded.university_ids, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.student_offers (id, name, provider, category, summary, eligibility, how_to_verify, url, countries, university_ids, status, source_url, last_verified, sort_order) values ('notion_education', 'Notion Plus for students', 'Notion', 'productivity', 'Notion''s Plus plan free for college and university students.', 'Students at an accredited college or university (not K-12).', 'Sign up with your school email, then Settings → Upgrade plan → Get free education plan.', 'https://www.notion.com/product/notion-for-education', array[]::text[], array[]::text[], 'active', 'https://www.notion.com/help/notion-for-education', '2026-10-22', 3) on conflict (id) do update set name = excluded.name, provider = excluded.provider, category = excluded.category, summary = excluded.summary, eligibility = excluded.eligibility, how_to_verify = excluded.how_to_verify, url = excluded.url, countries = excluded.countries, university_ids = excluded.university_ids, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.student_offers (id, name, provider, category, summary, eligibility, how_to_verify, url, countries, university_ids, status, source_url, last_verified, sort_order) values ('autodesk_education', 'Autodesk Education', 'Autodesk', 'design', 'One year of free access to Autodesk software for learning, renewable while you''re eligible. Not for commercial work.', 'Students and educators at qualified educational institutions.', 'Autodesk checks your student status when you sign up for education access.', 'https://www.autodesk.com/education/edu-software/overview', array[]::text[], array[]::text[], 'active', 'https://www.autodesk.com/education/home', '2026-10-22', 4) on conflict (id) do update set name = excluded.name, provider = excluded.provider, category = excluded.category, summary = excluded.summary, eligibility = excluded.eligibility, how_to_verify = excluded.how_to_verify, url = excluded.url, countries = excluded.countries, university_ids = excluded.university_ids, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.student_offers (id, name, provider, category, summary, eligibility, how_to_verify, url, countries, university_ids, status, source_url, last_verified, sort_order) values ('microsoft_365_education', 'Microsoft 365 Education', 'Microsoft', 'productivity', 'Free web versions of Word, Excel, PowerPoint, OneNote and Teams for students at eligible schools. What''s included depends on your school''s license.', 'Students at an eligible school or university.', 'Sign up with your school email address.', 'https://www.microsoft.com/en-us/education/products/microsoft-365', array[]::text[], array[]::text[], 'active', 'https://www.microsoft.com/en-us/education/products/microsoft-365', '2026-10-22', 5) on conflict (id) do update set name = excluded.name, provider = excluded.provider, category = excluded.category, summary = excluded.summary, eligibility = excluded.eligibility, how_to_verify = excluded.how_to_verify, url = excluded.url, countries = excluded.countries, university_ids = excluded.university_ids, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.student_offers (id, name, provider, category, summary, eligibility, how_to_verify, url, countries, university_ids, status, source_url, last_verified, sort_order) values ('uwi_microsoft_365', 'Microsoft 365 through UWI', 'The University of the West Indies', 'productivity', 'UWI gives every St. Augustine student an Office 365 account: email, OneDrive and Office apps such as Word, Excel and PowerPoint.', 'Registered UWI St. Augustine students.', 'Sign in with your UWI student account. Campus IT (sta.uwi.edu/cits) has setup guides.', 'https://uwi.edu/o365/', array[]::text[], array['uwi_st_augustine']::text[], 'active', 'https://uwi.edu/o365/', '2026-10-22', 6) on conflict (id) do update set name = excluded.name, provider = excluded.provider, category = excluded.category, summary = excluded.summary, eligibility = excluded.eligibility, how_to_verify = excluded.how_to_verify, url = excluded.url, countries = excluded.countries, university_ids = excluded.university_ids, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.student_offers (id, name, provider, category, summary, eligibility, how_to_verify, url, countries, university_ids, status, source_url, last_verified, sort_order) values ('uwi_pelican_perks', 'Pelican Perks', 'UWI Alumni Association', 'shopping', 'Discounts at partner businesses, many in Trinidad and Tobago. Partners and discounts change often.', 'UWI students with a valid UWI student ID.', 'Show your UWI student ID at the partner business.', 'https://uwi.edu/alumnionline/membership/pelican-perks', array[]::text[], array['uwi_st_augustine']::text[], 'active', 'https://uwi.edu/alumnionline/membership/pelican-perks', '2026-10-22', 7) on conflict (id) do update set name = excluded.name, provider = excluded.provider, category = excluded.category, summary = excluded.summary, eligibility = excluded.eligibility, how_to_verify = excluded.how_to_verify, url = excluded.url, countries = excluded.countries, university_ids = excluded.university_ids, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.student_offers (id, name, provider, category, summary, eligibility, how_to_verify, url, countries, university_ids, status, source_url, last_verified, sort_order) values ('spotify_premium_student_us', 'Spotify Premium Student (with Hulu)', 'Spotify', 'music', 'Discounted Spotify Premium for students; in the US it includes Hulu (With Ads) at no extra cost. Up to 4 years, re-verify every 12 months.', '18 or older and enrolled at a US Title IV accredited college or university.', 'Verified by SheerID — you may log in to your school portal or upload proof of enrollment.', 'https://www.spotify.com/us/student/', array['US']::text[], array[]::text[], 'active', 'https://support.spotify.com/us/account_payment_help/subscription_information/spotify-and-hulu', '2026-10-22', 8) on conflict (id) do update set name = excluded.name, provider = excluded.provider, category = excluded.category, summary = excluded.summary, eligibility = excluded.eligibility, how_to_verify = excluded.how_to_verify, url = excluded.url, countries = excluded.countries, university_ids = excluded.university_ids, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.student_offers (id, name, provider, category, summary, eligibility, how_to_verify, url, countries, university_ids, status, source_url, last_verified, sort_order) values ('apple_music_student', 'Apple Music student subscription', 'Apple', 'music', 'Discounted Apple Music for students, with Apple TV+ included. Up to 48 months; re-verify once a year.', 'Students at a college or university in a country where the student plan is offered.', 'In Apple Music choose Student → Verify Eligibility; checked by UNiDAYS or SheerID.', 'https://support.apple.com/106008', array['US']::text[], array[]::text[], 'active', 'https://support.apple.com/106008', '2026-10-22', 9) on conflict (id) do update set name = excluded.name, provider = excluded.provider, category = excluded.category, summary = excluded.summary, eligibility = excluded.eligibility, how_to_verify = excluded.how_to_verify, url = excluded.url, countries = excluded.countries, university_ids = excluded.university_ids, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.student_offers (id, name, provider, category, summary, eligibility, how_to_verify, url, countries, university_ids, status, source_url, last_verified, sort_order) values ('youtube_premium_student', 'YouTube Premium student membership', 'YouTube', 'music', 'Discounted YouTube Premium or YouTube Music Premium for students. Up to 4 years; re-verify every year.', 'Enrolled at a higher-education institution approved by SheerID, in a country where student plans are offered.', 'Pick your school on the SheerID form from YouTube''s student plan page.', 'https://support.google.com/youtube/answer/9158808', array['US']::text[], array[]::text[], 'active', 'https://support.google.com/youtube/answer/9158808', '2026-10-22', 10) on conflict (id) do update set name = excluded.name, provider = excluded.provider, category = excluded.category, summary = excluded.summary, eligibility = excluded.eligibility, how_to_verify = excluded.how_to_verify, url = excluded.url, countries = excluded.countries, university_ids = excluded.university_ids, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.student_offers (id, name, provider, category, summary, eligibility, how_to_verify, url, countries, university_ids, status, source_url, last_verified, sort_order) values ('adobe_creative_cloud_students', 'Adobe Creative Cloud for students', 'Adobe', 'design', 'A student and teacher discount on Creative Cloud Pro (all the Creative Cloud apps).', '13 or older and enrolled at an accredited school or qualifying online program; bought by someone 18+ with a credit card.', 'Confirm a school email at checkout, or send proof such as a student ID, schedule or transcript.', 'https://www.adobe.com/creativecloud/buy/students.html', array['US']::text[], array[]::text[], 'active', 'https://www.adobe.com/students', '2026-10-22', 11) on conflict (id) do update set name = excluded.name, provider = excluded.provider, category = excluded.category, summary = excluded.summary, eligibility = excluded.eligibility, how_to_verify = excluded.how_to_verify, url = excluded.url, countries = excluded.countries, university_ids = excluded.university_ids, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.student_offers (id, name, provider, category, summary, eligibility, how_to_verify, url, countries, university_ids, status, source_url, last_verified, sort_order) values ('amazon_prime_student', 'Prime Student', 'Amazon', 'shopping', 'A discounted Amazon Prime membership for college students, usually starting with a free trial.', 'Enrolled at a college or university in a country where Amazon offers Prime Student (such as the US, UK or Ireland).', 'Sign up on that country''s Amazon site, usually with your school (.edu) email.', 'https://www.amazon.com/joinstudent', array['US', 'GB', 'IE']::text[], array[]::text[], 'TODO_VERIFY', null, null, 12) on conflict (id) do update set name = excluded.name, provider = excluded.provider, category = excluded.category, summary = excluded.summary, eligibility = excluded.eligibility, how_to_verify = excluded.how_to_verify, url = excluded.url, countries = excluded.countries, university_ids = excluded.university_ids, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.student_offers (id, name, provider, category, summary, eligibility, how_to_verify, url, countries, university_ids, status, source_url, last_verified, sort_order) values ('uwi_endnote', 'EndNote for UWI students', 'UWI Libraries', 'software', 'The EndNote reference manager, free to download for UWI St. Augustine students.', 'UWI St. Augustine students.', 'Log in at my.uwi.edu (pick St. Augustine) with your student ID, then myDocuments → EndNote.', 'https://uwi-sta.libanswers.com/reference/faq/343584', array[]::text[], array['uwi_st_augustine']::text[], 'active', 'https://uwi-sta.libanswers.com/reference/faq/343584', '2026-10-22', 13) on conflict (id) do update set name = excluded.name, provider = excluded.provider, category = excluded.category, summary = excluded.summary, eligibility = excluded.eligibility, how_to_verify = excluded.how_to_verify, url = excluded.url, countries = excluded.countries, university_ids = excluded.university_ids, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.student_offers (id, name, provider, category, summary, eligibility, how_to_verify, url, countries, university_ids, status, source_url, last_verified, sort_order) values ('uwi_health_services', 'Campus Health Services', 'UWI St. Augustine Health Services Unit', 'other', 'A walk-in clinic and pharmacy on campus with free screenings and nurse evaluations; full-time registered students have the Student Health Plan.', 'Registered UWI St. Augustine students (the Student Health Plan is for full-time students).', 'Show your valid UWI student ID at the front desk.', 'https://sta.uwi.edu/HEALTH/about', array[]::text[], array['uwi_st_augustine']::text[], 'active', 'https://sta.uwi.edu/HEALTH/about', '2026-10-22', 14) on conflict (id) do update set name = excluded.name, provider = excluded.provider, category = excluded.category, summary = excluded.summary, eligibility = excluded.eligibility, how_to_verify = excluded.how_to_verify, url = excluded.url, countries = excluded.countries, university_ids = excluded.university_ids, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.student_offers (id, name, provider, category, summary, eligibility, how_to_verify, url, countries, university_ids, status, source_url, last_verified, sort_order) values ('uwi_counselling', 'Free counselling (CAPS)', 'UWI St. Augustine Counselling and Psychological Services', 'other', 'Free, confidential counselling for students, in person or online; no referral needed.', 'Students of The UWI St. Augustine.', 'Book with the counsellor for your faculty (contact details are in campus notices).', 'https://sta.uwi.edu/current-students2/', array[]::text[], array['uwi_st_augustine']::text[], 'TODO_VERIFY', null, null, 15) on conflict (id) do update set name = excluded.name, provider = excluded.provider, category = excluded.category, summary = excluded.summary, eligibility = excluded.eligibility, how_to_verify = excluded.how_to_verify, url = excluded.url, countries = excluded.countries, university_ids = excluded.university_ids, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.perk_programs (id, kind, name, provider, countries, summary, how_to, url, merchants, window_days, status, source_url, last_verified, sort_order) values ('aadvantage', 'loyalty', 'American Airlines AAdvantage', 'American Airlines', array[]::text[], 'Miles expire after 24 months with no earning or redeeming. Primary AAdvantage credit cardmembers keep them while the card is open.', 'Earn or redeem at least once every 24 months — even a small purchase with a partner counts.', 'https://www.aa.com/web/i18n/aadvantage-program/aadvantage-terms-and-conditions.html', array['american airlines', 'aadvantage']::text[], null, 'active', 'https://www.aa.com/web/i18n/aadvantage-program/aadvantage-terms-and-conditions.html', '2026-10-22', 0) on conflict (id) do update set kind = excluded.kind, name = excluded.name, provider = excluded.provider, countries = excluded.countries, summary = excluded.summary, how_to = excluded.how_to, url = excluded.url, merchants = excluded.merchants, window_days = excluded.window_days, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.perk_programs (id, kind, name, provider, countries, summary, how_to, url, merchants, window_days, status, source_url, last_verified, sort_order) values ('marriott_bonvoy', 'loyalty', 'Marriott Bonvoy', 'Marriott', array[]::text[], 'Points are forfeited after 24 months with no earning or redeeming, and can''t be reinstated.', 'Earn or redeem at least once every two years.', 'https://www.marriott.com/loyalty/points-expiration.mi', array['marriott']::text[], null, 'active', 'https://www.marriott.com/loyalty/terms/default.mi', '2026-10-22', 1) on conflict (id) do update set kind = excluded.kind, name = excluded.name, provider = excluded.provider, countries = excluded.countries, summary = excluded.summary, how_to = excluded.how_to, url = excluded.url, merchants = excluded.merchants, window_days = excluded.window_days, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.perk_programs (id, kind, name, provider, countries, summary, how_to, url, merchants, window_days, status, source_url, last_verified, sort_order) values ('hilton_honors', 'loyalty', 'Hilton Honors', 'Hilton', array[]::text[], 'Points expire after 24 months with no qualifying activity (a stay, card earning, a partner, or buying or donating points).', 'Do one qualifying activity every 24 months.', 'https://www.hilton.com/en/p/hilton-honors/ways-to-stay-active/', array['hilton']::text[], null, 'active', 'https://www.hilton.com/en/hilton-honors/support-faq/', '2026-10-22', 2) on conflict (id) do update set kind = excluded.kind, name = excluded.name, provider = excluded.provider, countries = excluded.countries, summary = excluded.summary, how_to = excluded.how_to, url = excluded.url, merchants = excluded.merchants, window_days = excluded.window_days, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.perk_programs (id, kind, name, provider, countries, summary, how_to, url, merchants, window_days, status, source_url, last_verified, sort_order) values ('starbucks_rewards', 'loyalty', 'Starbucks Rewards', 'Starbucks', array['US']::text[], 'Green-level Stars expire 6 months after the month you earn them. Gold and Reserve members'' Stars don''t expire.', 'A Star-earning purchase, a reward redemption or a $30+ digital reload in the month before pushes expiry back a month.', 'https://www.starbucks.com/rewards/terms/', array['starbucks']::text[], null, 'active', 'https://www.starbucks.com/rewards/terms/', '2026-10-22', 3) on conflict (id) do update set kind = excluded.kind, name = excluded.name, provider = excluded.provider, countries = excluded.countries, summary = excluded.summary, how_to = excluded.how_to, url = excluded.url, merchants = excluded.merchants, window_days = excluded.window_days, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.perk_programs (id, kind, name, provider, countries, summary, how_to, url, merchants, window_days, status, source_url, last_verified, sort_order) values ('caribbean_miles', 'loyalty', 'Caribbean Miles', 'Caribbean Airlines', array['TT', 'JM', 'BB', 'GY', 'BS']::text[], 'Caribbean Airlines'' miles program. We couldn''t confirm when miles expire — check your account and add the date here.', 'Log in to Caribbean Miles to see your balance and any expiry date.', 'https://www.caribbean-airlines.com/', array['caribbean airlines']::text[], null, 'TODO_VERIFY', null, null, 4) on conflict (id) do update set kind = excluded.kind, name = excluded.name, provider = excluded.provider, countries = excluded.countries, summary = excluded.summary, how_to = excluded.how_to, url = excluded.url, merchants = excluded.merchants, window_days = excluded.window_days, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.perk_programs (id, kind, name, provider, countries, summary, how_to, url, merchants, window_days, status, source_url, last_verified, sort_order) values ('massy_card', 'loyalty', 'Massy Card', 'Massy', array['TT']::text[], 'Points at Massy Stores and partners (1 point per TT$10 at launch). We couldn''t confirm if or when points expire.', 'Check your balance in the Massy Card app or on your receipt, and add it here with any expiry date.', 'https://massygroup.com/news-item/welcome-to-the-massy-card-welcome-to-more-rewards/', array['massy']::text[], null, 'TODO_VERIFY', 'https://massygroup.com/news-item/welcome-to-the-massy-card-welcome-to-more-rewards/', null, 5) on conflict (id) do update set kind = excluded.kind, name = excluded.name, provider = excluded.provider, countries = excluded.countries, summary = excluded.summary, how_to = excluded.how_to, url = excluded.url, merchants = excluded.merchants, window_days = excluded.window_days, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.perk_programs (id, kind, name, provider, countries, summary, how_to, url, merchants, window_days, status, source_url, last_verified, sort_order) values ('target_price_match', 'price_adjust', 'Target price match', 'Target', array['US']::text[], 'If Target lowers the price of an identical item within 14 days of your purchase, it refunds the difference. Clearance is excluded.', 'Bring the receipt to a store, or call 1-800-591-3869 for Target.com orders. Screenshots aren''t accepted — show the live price.', 'https://www.target.com/help/articles/policies-guidelines/price-match-guarantee', array['target']::text[], 14, 'active', 'https://www.target.com/help/articles/policies-guidelines/price-match-guarantee', '2026-10-22', 6) on conflict (id) do update set kind = excluded.kind, name = excluded.name, provider = excluded.provider, countries = excluded.countries, summary = excluded.summary, how_to = excluded.how_to, url = excluded.url, merchants = excluded.merchants, window_days = excluded.window_days, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.perk_programs (id, kind, name, provider, countries, summary, how_to, url, merchants, window_days, status, source_url, last_verified, sort_order) values ('best_buy_price_match', 'price_adjust', 'Best Buy price match', 'Best Buy', array['US']::text[], 'If Best Buy lowers its price during your return and exchange period, it matches the lower price on request — more than once. Open-box and clearance are excluded.', 'Online orders: chat or call 1-888-237-8289. Store purchases: Customer Service desk.', 'https://www.bestbuy.com/site/help-topics/price-match-guarantee/pcmcat290300050002.c?id=pcmcat290300050002', array['best buy', 'bestbuy']::text[], null, 'active', 'https://www.bestbuy.com/site/help-topics/price-match-guarantee/pcmcat290300050002.c?id=pcmcat290300050002', '2026-10-22', 7) on conflict (id) do update set kind = excluded.kind, name = excluded.name, provider = excluded.provider, countries = excluded.countries, summary = excluded.summary, how_to = excluded.how_to, url = excluded.url, merchants = excluded.merchants, window_days = excluded.window_days, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.perk_programs (id, kind, name, provider, countries, summary, how_to, url, merchants, window_days, status, source_url, last_verified, sort_order) values ('costco_price_adjustment', 'price_adjust', 'Costco price adjustment', 'Costco', array['US']::text[], 'If the price drops within 30 days of purchase, members can get the difference back. Costco can deny requests at its discretion.', 'Costco.com orders: the price adjustment form online. Warehouse purchases: the returns counter where you bought it.', 'https://customerservice.costco.com/app/answers/answer_view/a_id/628/~/price-match---costco.com-orders', array['costco']::text[], 30, 'active', 'https://customerservice.costco.com/app/answers/answer_view/a_id/628/~/price-match---costco.com-orders', '2026-10-22', 8) on conflict (id) do update set kind = excluded.kind, name = excluded.name, provider = excluded.provider, countries = excluded.countries, summary = excluded.summary, how_to = excluded.how_to, url = excluded.url, merchants = excluded.merchants, window_days = excluded.window_days, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.perk_programs (id, kind, name, provider, countries, summary, how_to, url, merchants, window_days, status, source_url, last_verified, sort_order) values ('macys_price_adjustment', 'price_adjust', 'Macy''s price adjustment', 'Macy''s', array['US']::text[], 'If an eligible item''s advertised price drops within 10 days of your order, Macy''s refunds the difference. Clearance and some items are excluded.', 'Request it from Macy''s customer service; it goes back to your original payment method.', 'https://www.macys.com/customer-service/articles/how-can-i-get-a-price-adjustment', array['macy''s', 'macys']::text[], 10, 'active', 'https://www.macys.com/customer-service/articles/how-can-i-get-a-price-adjustment', '2026-10-22', 9) on conflict (id) do update set kind = excluded.kind, name = excluded.name, provider = excluded.provider, countries = excluded.countries, summary = excluded.summary, how_to = excluded.how_to, url = excluded.url, merchants = excluded.merchants, window_days = excluded.window_days, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.perk_programs (id, kind, name, provider, countries, summary, how_to, url, merchants, window_days, status, source_url, last_verified, sort_order) values ('us_missing_money', 'unclaimed', 'Unclaimed money (US states)', 'NAUPA · MissingMoney.com', array['US']::text[], 'Forgotten bank balances, refunds, deposits and insurance payouts held by states. Searching is free.', 'Search your name on MissingMoney.com, plus your state''s own site. Never pay a finder to search.', 'https://www.missingmoney.com/', array[]::text[], null, 'active', 'https://unclaimed.org/search-for-your-unclaimed-property-its-free/', '2026-10-22', 10) on conflict (id) do update set kind = excluded.kind, name = excluded.name, provider = excluded.provider, countries = excluded.countries, summary = excluded.summary, how_to = excluded.how_to, url = excluded.url, merchants = excluded.merchants, window_days = excluded.window_days, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.perk_programs (id, kind, name, provider, countries, summary, how_to, url, merchants, window_days, status, source_url, last_verified, sort_order) values ('tt_unclaimed_securities', 'unclaimed', 'Unclaimed government bond payments', 'Central Bank of Trinidad and Tobago', array['TT']::text[], 'Unpaid interest and maturity payments on government bonds, treasury bills and notes. The Central Bank publishes the names.', 'Check the list, then call the Government Services Unit at 621-2288 or 235-2288.', 'https://www.central-bank.org.tt/notice-collection-unclaimed-funds', array[]::text[], null, 'active', 'https://www.central-bank.org.tt/notice-collection-unclaimed-funds', '2026-10-22', 11) on conflict (id) do update set kind = excluded.kind, name = excluded.name, provider = excluded.provider, countries = excluded.countries, summary = excluded.summary, how_to = excluded.how_to, url = excluded.url, merchants = excluded.merchants, window_days = excluded.window_days, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.perk_programs (id, kind, name, provider, countries, summary, how_to, url, merchants, window_days, status, source_url, last_verified, sort_order) values ('jm_unclaimed_balances', 'unclaimed', 'Unclaimed bank balances', 'Ministry of Finance and the Public Service', array['JM']::text[], 'Accounts untouched for 15+ years are published twice a year. Claim at your bank within a year of publication, then from the Accountant General.', 'Search the latest list on the Ministry''s publications page, then contact the bank named.', 'https://www.mof.gov.jm/documents/publications/', array[]::text[], null, 'active', 'https://mof.gov.jm/about/overview/faq/183-financial-regulations/22-how-can-i-obtain-my-money-published-as-unclaimed-balances-in-the-newspaper.html', '2026-10-22', 12) on conflict (id) do update set kind = excluded.kind, name = excluded.name, provider = excluded.provider, countries = excluded.countries, summary = excluded.summary, how_to = excluded.how_to, url = excluded.url, merchants = excluded.merchants, window_days = excluded.window_days, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.perk_programs (id, kind, name, provider, countries, summary, how_to, url, merchants, window_days, status, source_url, last_verified, sort_order) values ('bs_dormant_accounts', 'unclaimed', 'Dormant bank balances', 'Central Bank of The Bahamas', array['BS']::text[], 'Balances inactive for years are moved to the Central Bank for safekeeping until the owner claims them.', 'Ask the bank where you held the account — it makes the claim with the Central Bank for you.', 'https://www.centralbankbahamas.com/viewPDF/documents/2019-06-21-04-11-47-Dormant-Account-Guidelines.pdf', array[]::text[], null, 'active', 'https://www.centralbankbahamas.com/viewPDF/documents/2019-06-21-04-11-47-Dormant-Account-Guidelines.pdf', '2026-10-22', 13) on conflict (id) do update set kind = excluded.kind, name = excluded.name, provider = excluded.provider, countries = excluded.countries, summary = excluded.summary, how_to = excluded.how_to, url = excluded.url, merchants = excluded.merchants, window_days = excluded.window_days, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.perk_programs (id, kind, name, provider, countries, summary, how_to, url, merchants, window_days, status, source_url, last_verified, sort_order) values ('bb_inactive_accounts', 'unclaimed', 'Inactive bank accounts', 'Barbados banks', array['BB']::text[], 'Banks publish lists of long-inactive accounts before unclaimed money goes to the Central Bank of Barbados. We couldn''t find an official searchable list.', 'Ask any bank where you''ve had an account whether you''re on its inactive-accounts list.', 'https://www.centralbank.org.bb/', array[]::text[], null, 'TODO_VERIFY', null, null, 14) on conflict (id) do update set kind = excluded.kind, name = excluded.name, provider = excluded.provider, countries = excluded.countries, summary = excluded.summary, how_to = excluded.how_to, url = excluded.url, merchants = excluded.merchants, window_days = excluded.window_days, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.perk_programs (id, kind, name, provider, countries, summary, how_to, url, merchants, window_days, status, source_url, last_verified, sort_order) values ('libby', 'library', 'Libby', 'OverDrive', array[]::text[], 'Free e-books and audiobooks from your public library. No fees, no late fees.', 'Install Libby, find your library and add your library card.', 'https://www.overdrive.com/apps/libby', array[]::text[], null, 'active', 'https://help.libbyapp.com/en-us/6144.htm', '2026-10-22', 15) on conflict (id) do update set kind = excluded.kind, name = excluded.name, provider = excluded.provider, countries = excluded.countries, summary = excluded.summary, how_to = excluded.how_to, url = excluded.url, merchants = excluded.merchants, window_days = excluded.window_days, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.perk_programs (id, kind, name, provider, countries, summary, how_to, url, merchants, window_days, status, source_url, last_verified, sort_order) values ('kanopy', 'library', 'Kanopy', 'Kanopy', array['US']::text[], 'Free films and documentaries through participating libraries and universities.', 'Find your library on Kanopy and sign in with your library card.', 'https://www.kanopy.com/en/signup/find/publiclibrary', array[]::text[], null, 'active', 'https://help.kanopy.com/en-us/4171.htm', '2026-10-22', 16) on conflict (id) do update set kind = excluded.kind, name = excluded.name, provider = excluded.provider, countries = excluded.countries, summary = excluded.summary, how_to = excluded.how_to, url = excluded.url, merchants = excluded.merchants, window_days = excluded.window_days, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.perk_programs (id, kind, name, provider, countries, summary, how_to, url, merchants, window_days, status, source_url, last_verified, sort_order) values ('nalis', 'library', 'NALIS library card', 'NALIS', array['TT']::text[], 'Free for residents: e-books and audiobooks on Libby, popular magazines on Flipster and EBSCO research databases.', 'Register online, collect your card at a branch, then set your PIN for the digital library.', 'https://www.nalis.gov.tt/FAQs', array[]::text[], null, 'active', 'https://www.nalis.gov.tt/FAQs', '2026-10-22', 17) on conflict (id) do update set kind = excluded.kind, name = excluded.name, provider = excluded.provider, countries = excluded.countries, summary = excluded.summary, how_to = excluded.how_to, url = excluded.url, merchants = excluded.merchants, window_days = excluded.window_days, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.perk_programs (id, kind, name, provider, countries, summary, how_to, url, merchants, window_days, status, source_url, last_verified, sort_order) values ('jamaica_library_service', 'library', 'Jamaica Library Service', 'Jamaica Library Service', array['JM']::text[], 'Free computers and internet at 119 libraries; members can use EBSCO research databases.', 'Join at any parish or branch library.', 'https://jis.gov.jm/jamaica-library-service-embraces-use-technology-services/', array[]::text[], null, 'active', 'https://jis.gov.jm/jamaica-library-service-embraces-use-technology-services/', '2026-10-22', 18) on conflict (id) do update set kind = excluded.kind, name = excluded.name, provider = excluded.provider, countries = excluded.countries, summary = excluded.summary, how_to = excluded.how_to, url = excluded.url, merchants = excluded.merchants, window_days = excluded.window_days, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.perk_programs (id, kind, name, provider, countries, summary, how_to, url, merchants, window_days, status, source_url, last_verified, sort_order) values ('us_dot_flight_refunds', 'refund_rule', 'Cancelled or very late US flights', 'US Department of Transportation', array[]::text[], 'Flights to, from or within the US: if it''s cancelled or delayed 3+ hours (domestic) or 6+ hours (international) and you don''t accept another option, you''re owed a cash refund — within 7 business days for card payments.', 'Decline the rebooking or credit if you want the money back. If it doesn''t arrive, file a complaint with the DOT.', 'https://www.transportation.gov/individuals/aviation-consumer-protection/refunds', array[]::text[], null, 'active', 'https://www.transportation.gov/individuals/aviation-consumer-protection/refunds', '2026-10-22', 19) on conflict (id) do update set kind = excluded.kind, name = excluded.name, provider = excluded.provider, countries = excluded.countries, summary = excluded.summary, how_to = excluded.how_to, url = excluded.url, merchants = excluded.merchants, window_days = excluded.window_days, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.perk_programs (id, kind, name, provider, countries, summary, how_to, url, merchants, window_days, status, source_url, last_verified, sort_order) values ('eu261', 'refund_rule', 'Delayed or cancelled flights in Europe', 'European Union', array[]::text[], 'Flights leaving the EU, or into the EU on an EU airline: €250–€600 compensation when you arrive 3+ hours late or a late cancellation, unless the airline proves extraordinary circumstances.', 'Claim from the airline first; each EU country has a body that handles complaints.', 'https://europa.eu/youreurope/citizens/travel/passenger-rights/air/index_en.htm', array[]::text[], null, 'active', 'https://eur-lex.europa.eu/eli/reg/2004/261/oj/eng', '2026-10-22', 20) on conflict (id) do update set kind = excluded.kind, name = excluded.name, provider = excluded.provider, countries = excluded.countries, summary = excluded.summary, how_to = excluded.how_to, url = excluded.url, merchants = excluded.merchants, window_days = excluded.window_days, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.perk_programs (id, kind, name, provider, countries, summary, how_to, url, merchants, window_days, status, source_url, last_verified, sort_order) values ('us_billing_errors', 'refund_rule', 'Charged twice or for something you never got', 'Consumer Financial Protection Bureau', array['US']::text[], 'US credit cards: dispute billing errors in writing within 60 days of the statement that first shows them. You don''t have to pay the disputed amount while it''s investigated.', 'Call your card issuer, then send a letter to its billing-inquiries address.', 'https://www.consumerfinance.gov/consumer-tools/credit-cards/how-to-fix-mistakes-in-your-credit-card-bill/', array[]::text[], null, 'active', 'https://www.consumerfinance.gov/rules-policy/regulations/1026/13/', '2026-10-22', 21) on conflict (id) do update set kind = excluded.kind, name = excluded.name, provider = excluded.provider, countries = excluded.countries, summary = excluded.summary, how_to = excluded.how_to, url = excluded.url, merchants = excluded.merchants, window_days = excluded.window_days, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.perk_programs (id, kind, name, provider, countries, summary, how_to, url, merchants, window_days, status, source_url, last_verified, sort_order) values ('us_health_fsa', 'deadline_rule', 'Health FSA: use it or lose it', 'IRS', array['US']::text[], 'Money left in a health FSA at the end of the plan year is lost, unless your plan has a grace period (up to 2½ months) or a carryover (up to $680 for 2026) — never both.', 'Check your plan''s deadline and add your balance here so PerkScan reminds you.', 'https://www.irs.gov/publications/p969', array[]::text[], null, 'active', 'https://www.irs.gov/pub/irs-pdf/iw2w3.pdf', '2026-10-22', 22) on conflict (id) do update set kind = excluded.kind, name = excluded.name, provider = excluded.provider, countries = excluded.countries, summary = excluded.summary, how_to = excluded.how_to, url = excluded.url, merchants = excluded.merchants, window_days = excluded.window_days, status = excluded.status, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
