insert into public.local_events (id, title, summary, category, countries, regions, issuers, card_keywords, starts_on, ends_on, url, status, based_on, source_url, last_verified, sort_order) values ('us_medicare_open_enrollment_2026', 'Medicare Open Enrollment', 'Change your Medicare Advantage or drug plan for 2027, or switch between Original Medicare and Medicare Advantage. Plans must get your form by December 7.', 'enrollment', array['US']::text[], array[]::text[], array[]::text[], array[]::text[], '2026-10-15', '2026-12-07', 'https://www.medicare.gov/health-drug-plans/open-enrollment', 'confirmed', null, 'https://www.medicare.gov/health-drug-plans/open-enrollment', '2026-10-23', 2) on conflict (id) do update set title = excluded.title, summary = excluded.summary, category = excluded.category, countries = excluded.countries, regions = excluded.regions, issuers = excluded.issuers, card_keywords = excluded.card_keywords, starts_on = excluded.starts_on, ends_on = excluded.ends_on, url = excluded.url, status = excluded.status, based_on = excluded.based_on, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
