insert into public.local_events (id, title, summary, category, countries, regions, issuers, card_keywords, starts_on, ends_on, url, status, based_on, source_url, last_verified, sort_order) values ('us_fsa_year_end_2026', 'Spend your FSA before the year ends', 'If your health FSA runs on the calendar year, money left after December 31 is lost — unless your plan has a grace period or carryover.', 'deadline', array['US']::text[], array[]::text[], array[]::text[], array[]::text[], '2026-11-15', '2026-12-31', 'https://www.irs.gov/publications/p969', 'expected', 'The deadline depends on your plan year; most plans follow the calendar year.', 'https://www.irs.gov/publications/p969', '2026-10-23', 4) on conflict (id) do update set title = excluded.title, summary = excluded.summary, category = excluded.category, countries = excluded.countries, regions = excluded.regions, issuers = excluded.issuers, card_keywords = excluded.card_keywords, starts_on = excluded.starts_on, ends_on = excluded.ends_on, url = excluded.url, status = excluded.status, based_on = excluded.based_on, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.local_events (id, title, summary, category, countries, regions, issuers, card_keywords, starts_on, ends_on, url, status, based_on, source_url, last_verified, sort_order) values ('tt_scotia_mastercard_divali_cashback_2026', 'Scotiabank Mastercard Divali cash back', 'Last year: 5% cash back on Scotiabank Mastercard purchases, capped at TT$200–250 depending on the card. Check whether it''s running this year.', 'bank_promo', array['TT']::text[], array[]::text[], array['Scotiabank Trinidad & Tobago']::text[], array['mastercard']::text[], '2026-10-16', '2026-10-31', 'https://tt.scotiabank.com/personal/credit-cards/credit-card-promotions.html', 'expected', 'Ran October 16–31, 2025.', 'https://tt.scotiabank.com/personal/credit-cards/credit-card-promotions/mastercard-divali-cash-back.html', '2026-10-23', 5) on conflict (id) do update set title = excluded.title, summary = excluded.summary, category = excluded.category, countries = excluded.countries, regions = excluded.regions, issuers = excluded.issuers, card_keywords = excluded.card_keywords, starts_on = excluded.starts_on, ends_on = excluded.ends_on, url = excluded.url, status = excluded.status, based_on = excluded.based_on, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
insert into public.local_events (id, title, summary, category, countries, regions, issuers, card_keywords, starts_on, ends_on, url, status, based_on, source_url, last_verified, sort_order) values ('tt_scotia_visa_christmas_cashback_2026', 'Scotiabank Visa Christmas cash back', 'Last year: cash back for reaching a personal spending goal on local Visa purchases, sent by email. Open those emails — it was a condition.', 'bank_promo', array['TT']::text[], array[]::text[], array['Scotiabank Trinidad & Tobago']::text[], array['visa']::text[], '2026-12-15', '2027-01-15', 'https://tt.scotiabank.com/personal/credit-cards/credit-card-promotions.html', 'expected', 'Ran December 15, 2025 – January 15, 2026.', 'https://tt.scotiabank.com/personal/credit-cards/credit-card-promotions/2025-visa-cash-back.html', '2026-10-23', 6) on conflict (id) do update set title = excluded.title, summary = excluded.summary, category = excluded.category, countries = excluded.countries, regions = excluded.regions, issuers = excluded.issuers, card_keywords = excluded.card_keywords, starts_on = excluded.starts_on, ends_on = excluded.ends_on, url = excluded.url, status = excluded.status, based_on = excluded.based_on, source_url = excluded.source_url, last_verified = excluded.last_verified, sort_order = excluded.sort_order;
